const vocab=[[["bom", "good (masculine)"], ["dia", "day"], ["boa", "good (feminine)"]], [["tudo", "everything"], ["bem", "well"], ["ótimo", "great"]], [["meu", "my (masculine)"], ["nome", "name"], ["é", "is"]], [["prazer", "pleasure"], ["conhecer", "to meet / get to know"], ["você", "you"]], [["sou", "I am"], ["de", "from / of"], ["dos", "de + os"]], [["fala", "speak / speaks"], ["inglês", "English"], ["português", "Portuguese"]], [["pode", "can / could"], ["repetir", "to repeat"], ["devagar", "slowly"]], [["quero", "I want"], ["um", "a / one (masculine)"], ["café", "coffee"]], [["quanto", "how much"], ["custa", "costs"], ["reais", "Brazilian currency"]], [["onde", "where"], ["fica", "is located"], ["banheiro", "bathroom"]], [["como", "how"], ["foi", "was / went"], ["corrido", "hectic"]], [["gosto", "I like"], ["de", "of / from"], ["correr", "to run"]], [["vamos", "let’s / we go"], ["conversar", "to chat"], ["agora", "now"]], [["até", "until / see you"], ["amanhã", "tomorrow"], ["logo", "soon"]]];
const grammar=["Adjectives often agree with a noun: bom dia uses masculine bom; boa tarde uses feminine boa.", "Tudo bem? becomes a question through your intonation. The same words can be the answer: Tudo bem!", "É is a form of ser (to be). Meu nome é introduces your name; eu sou introduces who you are.", "Em + a verb describes an activity here: prazer em conhecer você. Você is the everyday Brazilian form of “you.”", "Sou is the eu form of ser. De + os becomes dos: dos Estados Unidos.", "With você, use fala. With eu, use falo: eu falo português. Portuguese can omit eu when the verb makes it clear.", "Pode + the infinitive makes a request: pode repetir? Add por favor to be polite.", "Quero is the eu form of querer. Um goes with masculine café; uma goes with feminine água.", "Quanto custa? asks the price of one item. For multiple items, use Quanto custam?", "Onde fica + a place asks where it is. O banheiro uses the masculine definite article o.", "Foi is a past-tense form of ser and ir. In Foi bom, it means “It was good.”", "Gostar needs de before the thing or activity you like: gosto de café; gosto de correr.", "Vamos + an infinitive invites a shared action: vamos conversar; vamos correr.", "Até appears in goodbyes: até amanhã, até logo, até mais. Amanhã means tomorrow; hoje means today."];
const dialogues=[["A: Bom dia! Tudo bem?", "B: Tudo bem! E você?", "Good morning! How are you? / All good! And you?"], ["A: Tudo bem?", "B: Tudo ótimo! E você?", "How are you? / Everything’s great! And you?"], ["A: Qual é seu nome?", "B: Meu nome é Courtney.", "What’s your name? / My name is Courtney."], ["A: Meu nome é Ana.", "B: Prazer em conhecer você!", "My name is Ana. / Nice to meet you!"], ["A: De onde você é?", "B: Eu sou dos Estados Unidos.", "Where are you from? / I’m from the United States."], ["A: Você fala inglês?", "B: Sim, e um pouco de português.", "Do you speak English? / Yes, and a little Portuguese."], ["A: Pode repetir, por favor?", "B: Claro! Mais devagar?", "Could you repeat that, please? / Of course! More slowly?"], ["A: Eu quero um café, por favor.", "B: Claro! Mais alguma coisa?", "I want a coffee, please. / Of course! Anything else?"], ["A: Quanto custa o café?", "B: Custa cinco reais.", "How much is the coffee? / It costs five reais."], ["A: Onde fica o banheiro?", "B: Fica ali, à direita.", "Where is the bathroom? / It’s over there, on the right."], ["A: Como foi seu dia?", "B: Foi corrido, mas foi bom!", "How was your day? / It was hectic, but it was good!"], ["A: Você gosta de correr?", "B: Sim! Eu gosto de correr.", "Do you like running? / Yes! I like running."], ["A: Vamos conversar?", "B: Sim! Vamos falar em português.", "Shall we chat? / Yes! Let’s speak in Portuguese."], ["A: Até amanhã!", "B: Até! Boa noite!", "See you tomorrow! / See you! Good night!"]];

const nextLessons=[["Eu corro três vezes por semana.", "I run three times a week.", "Use a number + vezes por semana for frequency.", "What does vezes mean?", ["Times", "Miles", "Today"], 0, [["três", "three"], ["vezes", "times"], ["semana", "week"]], "Corro is the eu form of correr. Uma vez means once; duas vezes means twice.", ["A: Você corre com frequência?", "B: Eu corro três vezes por semana.", "Do you run often? / I run three times a week."]], ["Hoje vou descansar.", "Today I am going to rest.", "Name a plan with vou + a verb.", "What does descansar mean?", ["To order", "To rest", "To travel"], 1, [["hoje", "today"], ["vou", "I am going"], ["descansar", "to rest"]], "Vou + an infinitive describes an intention: vou correr, vou estudar.", ["A: O que você vai fazer hoje?", "B: Hoje vou descansar.", "What are you going to do today? / Today I am going to rest."]], ["Estou com fome.", "I am hungry.", "Use estou com fome for hunger and estou com sede for thirst.", "Which phrase means I am thirsty?", ["Estou com sede.", "Estou com fome.", "Estou bem."], 0, [["fome", "hunger"], ["sede", "thirst"], ["com", "with"]], "Portuguese describes hunger with estar com: literally, to be with hunger.", ["A: Você quer comer?", "B: Sim, estou com fome.", "Do you want to eat? / Yes, I am hungry."]], ["Queria uma água, por favor.", "I would like a water, please.", "Queria is a common polite way to order in Brazil.", "Which article goes with água?", ["O", "Um", "Uma"], 2, [["queria", "I would like"], ["água", "water"], ["gelada", "cold (feminine)"]], "Água is feminine: uma água gelada. Café is masculine: um café quente.", ["A: O que você queria?", "B: Queria uma água, por favor.", "What would you like? / I would like a water, please."]], ["A conta, por favor.", "The bill, please.", "A short phrase that is useful after a meal.", "What are you asking for?", ["A table", "The bill", "A menu"], 1, [["conta", "bill"], ["mesa", "table"], ["cardápio", "menu"]], "A and o are definite articles. A conta means the bill; o cardápio means the menu.", ["A: Mais alguma coisa?", "B: Só a conta, por favor.", "Anything else? / Just the bill, please."]], ["Posso pagar com cartão?", "Can I pay by card?", "Posso + a verb asks permission or whether something is possible.", "What does cartão mean?", ["Cash", "Card", "Receipt"], 1, [["posso", "I can / may"], ["pagar", "to pay"], ["cartão", "card"]], "Posso is the eu form of poder. Com cartão means by card; em dinheiro means in cash.", ["A: Posso pagar com cartão?", "B: Sim, pode.", "Can I pay by card? / Yes, you can."]], ["Bom dia! Queria um café e uma água.", "Good morning! I would like a coffee and a water.", "Review week: build an order, then ask for the bill and pay.", "Which word connects the two drinks?", ["De", "E", "Com"], 1, [["e", "and"], ["um", "a (masculine)"], ["uma", "a (feminine)"]], "E joins items. Choose um or uma to match each noun, even in the same order.", ["A: Bom dia! Queria um café e uma água.", "B: Claro! Mais alguma coisa?", "Good morning! I would like a coffee and a water. / Of course! Anything else?"]], ["O que você gosta de fazer?", "What do you like to do?", "Ask about interests, then answer with gosto de + a verb.", "Which answer says I like to read?", ["Eu gosto de ler.", "Eu vou ler.", "Eu li."], 0, [["o que", "what"], ["fazer", "to do / make"], ["ler", "to read"]], "Gostar takes de before another verb: gostar de correr, gostar de ler.", ["A: O que você gosta de fazer?", "B: Eu gosto de correr e ler.", "What do you like to do? / I like running and reading."]], ["Você quer jogar tênis?", "Do you want to play tennis?", "Invite someone with você quer + an infinitive.", "Which verb means to play?", ["Correr", "Jogar", "Ler"], 1, [["quer", "want / wants"], ["jogar", "to play"], ["tênis", "tennis"]], "Você uses quer, while eu uses quero. The next verb stays in the infinitive.", ["A: Você quer jogar tênis?", "B: Sim! Vamos jogar amanhã?", "Do you want to play tennis? / Yes! Shall we play tomorrow?"]], ["Que horas são?", "What time is it?", "A practical question for making plans.", "What is being asked?", ["The price", "The date", "The time"], 2, [["horas", "hours"], ["duas", "two (feminine)"], ["meia", "half"]], "Say é uma hora for one; são duas horas for two. Duas e meia means two thirty.", ["A: Que horas são?", "B: São duas e meia.", "What time is it? / It is two thirty."]], ["Vamos nos encontrar às seis.", "Let’s meet at six.", "Use às + an hour to arrange a meeting.", "What time are you meeting?", ["Six", "Two", "Ten"], 0, [["encontrar", "to meet / find"], ["seis", "six"], ["às", "at (before plural hours)"]], "Às combines a + as. At one is à uma; at six is às seis.", ["A: Que horas vamos nos encontrar?", "B: Vamos nos encontrar às seis.", "What time shall we meet? / Let’s meet at six."]], ["Ontem fui correr.", "Yesterday I went for a run.", "Start describing yesterday with ontem and fui.", "Which word means yesterday?", ["Hoje", "Amanhã", "Ontem"], 2, [["ontem", "yesterday"], ["fui", "I went / was"], ["correr", "to run"]], "Fui is a past form of ir and ser. In fui correr, it means I went to run.", ["A: O que você fez ontem?", "B: Ontem fui correr.", "What did you do yesterday? / Yesterday I went for a run."]], ["Foi divertido!", "It was fun!", "Use foi + a description when talking about an experience.", "What does divertido mean?", ["Difficult", "Fun", "Expensive"], 1, [["foi", "it was / went"], ["divertido", "fun"], ["difícil", "difficult"]], "Foi is a past form of ser or ir. An adjective after foi describes how something was.", ["A: Como foi o jogo?", "B: Foi divertido!", "How was the game? / It was fun!"]], ["Amanhã vou jogar tênis. Você quer ir?", "Tomorrow I am going to play tennis. Do you want to go?", "Review: invite someone, agree on a time, and describe yesterday.", "Which word signals a future day?", ["Ontem", "Amanhã", "Hoje"], 1, [["amanhã", "tomorrow"], ["ir", "to go"], ["jogo", "game"]], "Compare ontem fui (past) with amanhã vou (future intention). The time word helps establish context.", ["A: Amanhã vou jogar tênis. Você quer ir?", "B: Sim! Vamos nos encontrar às seis.", "Tomorrow I am going to play tennis. Do you want to go? / Yes! Let’s meet at six."]]];
nextLessons.forEach(u=>{lessons.push(u.slice(0,6));vocab.push(u[6]);grammar.push(u[7]);dialogues.push(u[8]);});
const wins=[["Practical · Finish one postponed task that takes under five minutes", "Connection · Send someone a thoughtful message or voice note", "Joy · Enjoy your coffee without multitasking"], ["Practical · Clear one small surface you use every day", "Connection · Ask someone how their day is going and listen", "Joy · Play a favorite song and give it your full attention"], ["Practical · Make one appointment or reply you’ve been putting off", "Connection · Tell someone one specific thing you appreciate about them", "Joy · Read a few pages of something just for pleasure"], ["Practical · Put one thing back where it belongs", "Connection · Share something that made you laugh with a friend", "Joy · Step outside for a few minutes without scrolling"], ["Practical · Write down one errand so you don’t have to keep remembering it", "Connection · Check in with someone you haven’t talked to lately", "Joy · Take a photo of something ordinary you find beautiful"], ["Practical · Tidy one tiny corner, then stop", "Connection · Give someone a sincere compliment", "Joy · Try something creative for five minutes, without judging it"], ["Practical · Set out one thing that will make tomorrow easier", "Connection · Suggest a small plan with someone you enjoy", "Joy · Leave a little time for something you feel like doing"]];
const brainLessons=[["IF–THEN PLANNING", "Wanting to do something and deciding when to begin are different steps. An if–then plan connects a clear cue with a specific action: “If X happens, then I will do Y.” A small first action makes the plan easier to try. Pick a cue you can recognize, rather than waiting for the right mood.", "Instead of “I should practice Portuguese,” try “After I put my coffee down, I’ll say today’s phrase aloud once.” You can continue if you want; beginning is the planned action.", ["Choose one thing you want to start.", "Name a cue you already encounter.", "Write: “If / after ___, then I will ___.” Try it once and adjust if the cue is impractical."], "What could you make easier to begin?", "Implementation intentions · National Cancer Institute", "https://cancercontrol.cancer.gov/brp/research/constructs/implementation-intentions"], ["FACT, INTERPRETATION, NEED", "A thought can feel convincing without being the only explanation. Reframing means examining it fairly, not forcing a positive spin. Separate what happened from what you think it means. Then look for a more balanced interpretation that fits the evidence and leaves room for uncertainty.", "A short reply is the fact. “They’re annoyed with me” is an interpretation. “I’d like clarity” is a need you can acknowledge without treating the interpretation as proven.", ["Write the event in neutral language.", "Write your first interpretation, then one plausible alternative.", "Choose a next step based on what you know: ask, wait, or return to your day."], "What else might explain this?", "Reframing unhelpful thoughts · NHS", "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"], ["RETRIEVAL PRACTICE", "Recognizing a phrase while reading it is different from recalling it yourself. Retrieval practice means trying to bring information to mind before checking the answer. Research supports it as a learning strategy. Keep the attempt low stakes, and use feedback to correct what you missed. Getting something wrong gives you a useful target for the next review.", "After reading your Portuguese dialogue, cover it and try to remember one phrase. Then check the wording. This tests recall rather than whether the sentence looks familiar.", ["Read a short piece of learning material.", "Hide it and explain two ideas or phrases from memory.", "Check, correct, and try again later."], "What can you explain without looking?", "Retrieval practice · research and educator guide", "https://www.retrievalpractice.org/retrievalpractice"], ["TURN A WORRY INTO A NEXT STEP", "Some worries point to a problem you can act on; others are hypothetical questions you cannot settle right now. Sorting the two can help you choose what to do next. For a practical problem, identify one manageable action. For a hypothetical worry, acknowledge it and gently return your attention to the present.", "“I haven’t prepared for the meeting” has a next step: outline your opening points. “What if everyone thinks I’m terrible?” cannot be solved by rehearsing every possible reaction.", ["Name what is worrying you.", "Ask: is there a concrete action I can take now?", "Take one useful step, or redirect your attention to something in front of you."], "What are you curious about today?", "Tackling your worries · NHS", "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/tackling-your-worries/"], ["MAKE A PLAN FOR THE OBSTACLE", "If–then plans can also prepare you for a predictable obstacle. Name the situation that usually interrupts your intention and decide on a workable response in advance. Aim for flexibility: a fallback should help you adapt, rather than turn an already full day into a test of willpower.", "“If my afternoon runs late, then I’ll do one Portuguese review phrase before dinner.” That keeps the learning action available without requiring the full lesson at a fixed time.", ["Choose a recurring obstacle.", "Decide on one realistic fallback action.", "Write the if–then sentence and put it where you’ll notice it."], "What deserves your attention first?", "Implementation intentions · National Cancer Institute", "https://cancercontrol.cancer.gov/brp/research/constructs/implementation-intentions"], ["CHECK THE ALL-OR-NOTHING STORY", "Words such as “always,” “never” and “completely” can hide the middle ground. A balanced thought includes the difficulty and the evidence that complicates it. You do not need to pretend a setback feels good. Try making the description more precise so it can guide a useful response.", "“I got nothing done” might become “I didn’t finish the main task, but I answered the urgent questions and identified the next step.” The unfinished work remains; the whole day is no longer erased.", ["Catch one sweeping statement.", "List a fact that supports it and a fact that complicates it.", "Rewrite it with more specific language."], "What would make this belief less certain?", "Reframing unhelpful thoughts · NHS", "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"], ["A REVIEW THAT LEADS TO AN ADJUSTMENT", "A weekly review can be a practical learning exercise rather than a scorecard. Start with an observation, consider the conditions around it, and choose a small adjustment to try. Keep the conclusion tentative: one week is information, not a verdict about your discipline or personality.", "“I practiced more often when the lesson was open with my coffee” suggests a useful setup. “I’m good or bad at routines” offers much less guidance for next week.", ["Name one thing that worked and one thing that was difficult.", "Look at timing, environment and workload before judging yourself.", "Choose one small change and a time to review whether it helped."], "What will you carry into next week?", "A practical reflection exercise", null]];
const selfHelpReadings=[["THE FIRST STEP DOESN’T HAVE TO BE IMPRESSIVE.", "It’s easy to imagine a better routine as something a more organized version of you will eventually do. But a routine has to fit the person who is here now, with an ordinary amount of time and energy. A first step can be almost embarrassingly small: opening the document, saying one phrase, putting one item away.", "Small does not mean the larger goal matters less. It means you are choosing a place to begin. Once you start, you can decide whether to continue. You also get useful information: was the cue obvious, was the action realistic, and did the setup help? Let that information guide the next attempt instead of turning the outcome into a judgment about yourself."], ["YOU CAN LISTEN TO A FEELING WITHOUT LETTING IT WRITE THE WHOLE STORY.", "A feeling can deserve your attention even when your first explanation needs another look. You might feel unsettled by a short message, disappointed by a changed plan, or nervous before a conversation. Acknowledging that experience does not require deciding that your worst interpretation is correct.", "Try leaving a little space between “this hurt” and “this is what it means.” In that space, you can ask a question, notice what you need, or give yourself time. A balanced account might still include disappointment. The aim is not to talk yourself out of caring; it is to give yourself more than one way to understand what happened."], ["LEARNING CAN FEEL MESSY WHILE IT IS HAPPENING.", "Reading a clear explanation is satisfying. Trying to explain it yourself can be less comfortable: a word goes missing, an example feels fuzzy, or you realize you only understood half of it. That moment can be useful. It shows you what to return to.", "Treat practice as a conversation with the material. Try, check, correct, and try again. You do not need a perfect performance to make the attempt worthwhile. With Portuguese, that might mean remembering the greeting but forgetting the reply. Keep the greeting, revisit the reply, and put them together next time. Progress can look like a slightly clearer second attempt rather than an effortless first one."], ["NOT EVERY QUESTION NEEDS AN ANSWER TODAY.", "Some thoughts arrive dressed as urgent tasks: What if this goes wrong? What will they think? What if I should have chosen differently? Before trying to answer, ask whether the question points to something you can actually do. Preparing one useful thing is different from rehearsing every possible future.", "If there is an action, make it specific enough to finish. If there is not, you can acknowledge the uncertainty and return to what is in front of you. That may take more than one attempt. You are not required to feel completely certain before making lunch, reading a page, or enjoying a conversation. Ordinary life can keep happening while a question remains open."], ["A FALLBACK IS PART OF A PLAN.", "A plan made on a quiet day can forget about the busy one. Meetings run over, an errand takes longer, or your attention is already stretched. A useful fallback gives you a smaller version of an action when the original version no longer fits.", "The purpose is to adapt rather than bargain with yourself all evening. Choose the fallback before you need it, and make it something you would actually accept as enough. Some days, stopping or rescheduling is the sensible response. A plan that can accommodate real life is easier to learn from than one that labels every change a failure."], ["DESCRIBE THE DAY BEFORE YOU GRADE IT.", "“A bad day” can hide several different things: a frustrating conversation, unfinished work, low energy, or a plan that changed. A more specific description gives you more options. A conversation might need repair. A task might need a clearer first step. Low energy might call for rest.", "You do not have to rescue the day with a list of positives. Start by describing it accurately, including the parts that went reasonably well. Then choose a response that fits the actual problem. One difficult hour can be difficult without becoming evidence that you are doing everything wrong. Precision can be a gentler way of talking to yourself."], ["TAKE THE LESSON, NOT THE VERDICT.", "Looking back can become an argument about whether you tried hard enough. A more useful review asks what the week taught you about your setup. When did a task feel easier? Which commitments crowded each other? What helped you enjoy yourself?", "Choose one adjustment from what you notice. Keep it small enough to observe: a different time, a clearer boundary, fewer steps, or a little more preparation. You do not need to redesign your whole life by Sunday evening. Let next week be a chance to test the adjustment, then learn from that attempt too. A review can end with curiosity rather than a grade."]];
const health=[['MAKE MOVEMENT ENJOYABLE.','Pick an activity you enjoy today. Your training plan and how you feel can guide the intensity.'],['RECOVERY HAS A PLACE.','Leave room for rest in your training week. A quieter day can still be intentional.'],['PLAN A SIMPLE MEAL.','Think ahead about a meal or snack you enjoy so a busy day feels easier.'],['MAKE SLEEP A LITTLE EASIER.','Choose one small part of your evening routine that helps you wind down.'],['CHECK IN WITH YOURSELF.','Before a workout, notice how you feel and adjust your plans when needed.'],['TAKE A MOVEMENT BREAK.','A short walk can give your workday a change of scene.'],['CELEBRATE CONSISTENCY.','Notice what you showed up for this week, even if it was small.']];
const career=[['TURN NOTES INTO DECISIONS.','Ask an AI tool to organize nonconfidential notes into decisions, owners and open questions. Verify each item against the notes.'],['ASK FOR THE GAPS.','Share a nonconfidential plan and ask what questions are still unanswered. Decide which suggestions are relevant.'],['WRITE A CLEARER BRIEF.','State the audience, desired outcome, constraints and what a successful result looks like.'],['COMPARE TWO OPTIONS.','Ask for a comparison using criteria you choose. Check claims and make the decision yourself.'],['PRACTICE A CONVERSATION.','Role-play an ordinary work conversation, then identify one clearer question you could ask.'],['CUT THE FLUFF.','Ask for a shorter version of a nonconfidential draft while preserving its meaning. Read it carefully before sharing.'],['SAVE A USEFUL PATTERN.','Turn a repeated task into a short checklist. Keep the steps that help and remove the rest.']];
const facts=[['VENUS TAKES ITS TIME.','Venus rotates more slowly than it travels around the Sun. Its sidereal rotation takes about 243 Earth days; its year takes about 225.','https://science.nasa.gov/venus/facts/'],['OCTOPUSES HAVE THREE HEARTS.','Two hearts pump blood to the gills. One pumps it to the rest of the body.','https://www.nhm.ac.uk/discover/octopuses-keep-surprising-us-here-are-eight-examples-how.html'],['THE SUN IS A STAR.','Our closest star supplies the light and heat that make life on Earth possible.','https://science.nasa.gov/sun/facts/'],['THE OCEAN HAS ROOM TO EXPLORE.','The ocean covers about 71 percent of Earth’s surface.','https://oceanservice.noaa.gov/facts/oceanwater.html'],['MARS HAS TWO MOONS.','Phobos and Deimos are the two small moons orbiting Mars.','https://science.nasa.gov/mars/facts/'],['SATURN IS LIGHT FOR ITS SIZE.','Saturn’s average density is lower than water’s. A hypothetical bathtub large enough is another matter.','https://science.nasa.gov/saturn/facts/'],['MOONLIGHT IS BORROWED LIGHT.','The Moon shines by reflecting sunlight.','https://science.nasa.gov/moon/facts/']];
